param([string]$CaseId='')
$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';$root='C:\JudasValidation';$base='http://192.168.122.1:8872';$m=$null
function Upload($p,$n){Invoke-WebRequest -UseBasicParsing "$base/$n" -Method Post -InFile $p|Out-Null}
try{
 $m=(Invoke-WebRequest -UseBasicParsing "$base/m78-final-cold-repair-v1.json").Content|ConvertFrom-Json;$scratch=$m.scratch;$out=$m.output;$case=@($m.cases|Where-Object {$_.id -eq $CaseId});if($case.Count -ne 1){throw 'Unique explicit prepared case required'};$case=$case[0]
 $library=[IO.File]::ReadAllText("$out\m78-final-repair-library.json")|ConvertFrom-Json;if((Get-FileHash $library.archive).Hash.ToLower() -ne $library.archiveSHA256){throw 'Final library changed'}
 if((Get-PSDrive C).Free -lt 18MB){throw 'Insufficient owned case headroom'};$name="m78-final-repair-$CaseId";$exe="$root\Build\Release\$name.exe";if(Test-Path $exe){throw 'Preserve existing final executable'}
 Import-Module "$root\VS2022\Common7\Tools\Microsoft.VisualStudio.DevShell.dll";Enter-VsDevShell -VsInstallPath "$root\VS2022" -SkipAutomaticLocation -DevCmdArguments '-arch=x64 -host_arch=x64';Set-Location "$root\Build";$objects=@();$rows=@();$ErrorActionPreference='Continue'
 foreach($u in $case.inputs){
  $obj="$scratch\objects\$($u.objectName)"
  if($u.reuseOriginal){if(Test-Path $obj){throw 'Preserve previous generated object'};Invoke-WebRequest -UseBasicParsing $u.objectURL -OutFile $obj;if((Get-FileHash $obj).Hash.ToLower() -ne $u.originalObjectSHA256){throw 'Original object mismatch'}}else{
   $source=Join-Path "$scratch\source" $u.path;if((Get-FileHash $source).Hash.ToLower() -ne $u.sha256){throw 'Fresh case source mismatch'};$flags=[string]$case.compilerFlags;$flags=[regex]::Replace($flags,'/Fo"[^"]*"',('/Fo"'+$obj+'"'),'IgnoreCase');$flags=[regex]::Replace($flags,'/Fd"[^"]*"',('/Fd"'+$scratch+'\objects\case.pdb"'),'IgnoreCase');$flags='/I"'+$scratch+'\source\src" /I"'+$root+'\Source\third_party" '+$flags+' "'+$source+'"';$rsp="$scratch\objects\$($u.objectName)-compile.rsp";[IO.File]::WriteAllText($rsp,$flags,[Text.UTF8Encoding]::new($false));$log="$out\$name-$($u.objectName)-compile.log";[IO.File]::WriteAllText($log,'');& cl.exe "@$rsp" 2>&1|Tee-Object -FilePath $log;$code=$LASTEXITCODE;Upload $log ([IO.Path]::GetFileName($log));if($code -ne 0){throw 'Fresh case compile failed'}
  }
  $objects+=$obj;$rows+=@{source=$u.path;sourceSHA256=$u.sha256;reuseOriginal=$u.reuseOriginal;object=$obj;objectSHA256=(Get-FileHash $obj).Hash.ToLower();bytes=(Get-Item $obj).Length}
 }
 $link=[string]$case.linkFlags;$link=[regex]::Replace($link,'/OUT:"[^"]*"',('/OUT:"'+$exe+'"'),'IgnoreCase');$link=[regex]::Replace($link,'RELEASE\\JUDAS_ENGINE\.LIB',('"'+$library.archive+'"'),'IgnoreCase');$link=[regex]::Replace($link,'/PDB:"[^"]*"',('/PDB:"'+$scratch+'\objects\case-link.pdb"'),'IgnoreCase');$link=[regex]::Replace($link,'/IMPLIB:"[^"]*"',('/IMPLIB:"'+$scratch+'\objects\case.lib"'),'IgnoreCase');foreach($o in $objects){$link+=' "'+$o+'"'};$rsp="$scratch\objects\$CaseId-link.rsp";[IO.File]::WriteAllText($rsp,$link,[Text.UTF8Encoding]::new($false));$log="$out\$name-link.log";[IO.File]::WriteAllText($log,'');& link.exe "@$rsp" 2>&1|Tee-Object -FilePath $log;$code=$LASTEXITCODE;Upload $log ([IO.Path]::GetFileName($log));if($code -ne 0){throw 'Fresh case link failed'}
 $env:GALLIUM_DRIVER='llvmpipe';$env:JUDAS_ENGINE_ROOT="$root\Source";$env:TEMP="$out\temp";$env:TMP=$env:TEMP;New-Item -ItemType Directory $env:TEMP -Force|Out-Null
 foreach($n in @('M78_DIAGNOSTIC_PERSIST_DRIVE_IMPULSES','JUDAS_DIAGNOSTIC_RESTORE_DRIVES','JUDAS_BOUNDARY_REPLAY_CAPTURED_NATIVE','JUDAS_BOUNDARY_REPLAY_MODE','JUDAS_BOUNDARY_DISCARD_FIRST_JOINT_SEEDS','JUDAS_BOUNDARY_ORACLE_FIRST_SOLVE','JUDAS_BOUNDARY_ORACLE_ALL_SOLVES','JUDAS_DIAGNOSTIC_CONTINUE_WRITE','JUDAS_TEST_SCRIPT')){[Environment]::SetEnvironmentVariable($n,$null,'Process')}
 $runs=@()
 foreach($run in $case.runs){
  $rn="m78-final-repair-$($run.id)";if(Test-Path "$out\$rn.json"){throw 'Preserve previous final run receipt'}
  if($run.copyExactColdFrom){$dest=$run.arguments[0];if(Test-Path $dest){throw 'Preserve exact cold directory'};if((Get-FileHash "$($run.copyExactColdFrom)\slots\m77.save").Hash.ToLower() -ne $run.expectedSaveSHA256){throw 'Original a106 input changed'};New-Item -ItemType Directory $dest|Out-Null;Copy-Item "$($run.copyExactColdFrom)\project","$($run.copyExactColdFrom)\slots" $dest -Recurse;if((Get-FileHash "$dest\slots\m77.save").Hash.ToLower() -ne $run.expectedSaveSHA256){throw 'Exact copied a106 mismatch'}}
  $options=@{FilePath=$exe;WorkingDirectory="$root\Source";PassThru=$true;RedirectStandardOutput="$out\$rn.stdout.log";RedirectStandardError="$out\$rn.stderr.log"};if($run.arguments.Count){$options.ArgumentList=@($run.arguments)};$watch=[Diagnostics.Stopwatch]::StartNew();$p=Start-Process @options;[void]$p.Handle;if(!$p.WaitForExit(600000)){Stop-Process -Id $p.Id -Force;$exit='owned final case timed out'}else{$p.Refresh();$exit=$p.ExitCode};$watch.Stop();$files=@()
  if($run.arguments.Count -and (Test-Path $run.arguments[0] -PathType Container)){
   $dest=$run.arguments[0];foreach($f in @(Get-ChildItem $dest -File|Where-Object {$_.Extension -in '.json','.jsonl'})+@(Get-ChildItem "$dest\slots" -File -ErrorAction SilentlyContinue)){$report="$rn-$($f.Name)";Upload $f.FullName $report;$files+=@{path=$f.FullName;reportName=$report;sha256=(Get-FileHash $f.FullName).Hash.ToLower();bytes=$f.Length}}
  }
  $row=@{scope=$m.scope;case=$CaseId;run=$run.id;exitCode=$exit;seconds=$watch.Elapsed.TotalSeconds;executableSHA256=(Get-FileHash $exe).Hash.ToLower();archiveSHA256=$library.archiveSHA256;sourceBundleSHA256=$m.archiveSHA256;arguments=@($run.arguments);expectedSaveSHA256=$run.expectedSaveSHA256;files=$files;freeBytes=(Get-PSDrive C).Free};$runs+=$row;$rp="$out\$rn.json";$row|ConvertTo-Json -Depth 6|Set-Content $rp -Encoding UTF8;Upload "$out\$rn.stdout.log" "$rn.stdout.log";Upload "$out\$rn.stderr.log" "$rn.stderr.log";Upload $rp "$rn.json"
 }
 $rp="$out\$name-build.json";@{scope=$m.scope;case=$CaseId;objects=$rows;librarySHA256=$library.archiveSHA256;executable=$exe;executableSHA256=(Get-FileHash $exe).Hash.ToLower();executableBytes=(Get-Item $exe).Length;linkerResponse=$link;runs=$runs;freeBytes=(Get-PSDrive C).Free}|ConvertTo-Json -Depth 7|Set-Content $rp -Encoding UTF8;Upload $rp ([IO.Path]::GetFileName($rp))
 $all=@($exe)+$objects;$zip="$scratch\$name-generated.zip";Add-Type -AssemblyName System.IO.Compression;Add-Type -AssemblyName System.IO.Compression.FileSystem;$z=[IO.Compression.ZipFile]::Open($zip,[IO.Compression.ZipArchiveMode]::Create);try{foreach($p in $all){[void][IO.Compression.ZipFileExtensions]::CreateEntryFromFile($z,$p,[IO.Path]::GetFileName($p),[IO.Compression.CompressionLevel]::Optimal)}}finally{$z.Dispose()};Upload $zip ([IO.Path]::GetFileName($zip));$files=@();foreach($p in $all){$files+=@{path=$p;name=[IO.Path]::GetFileName($p);bytes=(Get-Item $p).Length;sha256=(Get-FileHash $p).Hash.ToLower()}};$rp="$out\$name-archive.json";@{scope='Archive only; cleanup requires host verification';archiveName=[IO.Path]::GetFileName($zip);archiveSHA256=(Get-FileHash $zip).Hash.ToLower();archiveBytes=(Get-Item $zip).Length;archivePath=$zip;files=$files}|ConvertTo-Json -Depth 5|Set-Content $rp -Encoding UTF8;Upload $rp ([IO.Path]::GetFileName($rp))
}catch{if(!$m){$out="$root\M78ColdRepairFinalResults"};New-Item -ItemType Directory $out -Force|Out-Null;[string]$_.Exception.Message|Set-Content "$out\m78-final-repair-$CaseId-error.txt";Upload "$out\m78-final-repair-$CaseId-error.txt" "m78-final-repair-$CaseId-error.txt";exit 1}
